SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- Installer fence only: use a single REPEATABLE READ transaction.
-- No persistent changes, claims, source values, or sequence allocation here.
-- Row coverage: PMB public, all PDC private/Broome, Auth, Storage, both Karratha,
-- and cron job configuration. Concurrent non-MVCC sequence counters are not
-- claimed by this row fence; the candidate contains no allocation/reset call.
-- Own native677 bodies and the five facade ACL/metadata are also gated by the
-- exact before/after proofs embedded in source-candidate.sql.
DO $display_fence_environment$ BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR auth.uid() IS NOT NULL
  OR current_setting('transaction_isolation') NOT IN('repeatable read','serializable') THEN
  RAISE EXCEPTION 'Claim-free privileged consistent installer transaction required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.pdc_staging_environment_sentinel
  WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')
  OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL THEN
  RAISE EXCEPTION 'Exact nonproduction staging required';END IF;
 PERFORM set_config('search_path','public,extensions',true);
END $display_fence_environment$;
CREATE TEMP VIEW k135_display_catalog_probe AS
SELECT 'function'::text kind,p.oid::oid object_id,0::integer sub_id,CASE WHEN p.oid IN(
 'public.k135_get_pdc_email_vehicle_board_snapshot()'::regprocedure,
 'public.k135_get_pdc_email_vehicle_location_snapshot()'::regprocedure,
 'public.k135_get_station_workshop_snapshot(text,date,date)'::regprocedure,
 'public.k135_get_workshop_snapshot(date,date)'::regprocedure,
 'public.k135_get_workshop_eligibility_snapshot()'::regprocedure)
 THEN md5((to_jsonb(p)-'prosrc')::text)
 ELSE md5(to_jsonb(p)::text||pg_get_functiondef(p.oid)) END fingerprint FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema' AND p.prokind='f' AND NOT(n.nspname='karratha135_pdc'
 AND p.proname IN('shared_navision_display_map_20261004','overlay_shared_navision_display_20261004','read_shared_navision_display_20261004'))
UNION ALL
SELECT 'relation'::text kind,c.oid::oid object_id,0::integer sub_id,md5(to_jsonb(c)::text) fingerprint FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'sequence_definition'::text kind,s.seqrelid::oid object_id,0::integer sub_id,md5(to_jsonb(s)::text) fingerprint FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'index'::text kind,i.indexrelid::oid object_id,0::integer sub_id,md5(to_jsonb(i)::text) fingerprint FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'constraint'::text kind,c.oid::oid object_id,0::integer sub_id,md5(to_jsonb(c)::text) fingerprint FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'trigger'::text kind,t.oid::oid object_id,0::integer sub_id,md5(to_jsonb(t)::text) fingerprint FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'policy'::text kind,p.oid::oid object_id,0::integer sub_id,md5(to_jsonb(p)::text) fingerprint FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'namespace'::text kind,n.oid::oid object_id,0::integer sub_id,md5(to_jsonb(n)::text) fingerprint FROM pg_namespace n WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'roles'::text kind,r.oid::oid object_id,0::integer sub_id,md5(to_jsonb(r)::text) fingerprint FROM pg_roles r WHERE true
UNION ALL
SELECT 'type'::text kind,t.oid::oid object_id,0::integer sub_id,md5(to_jsonb(t)::text) fingerprint FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'enum'::text kind,e.oid::oid object_id,0::integer sub_id,md5(to_jsonb(e)::text) fingerprint FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'rule'::text kind,r.oid::oid object_id,0::integer sub_id,md5(to_jsonb(r)::text||pg_get_ruledef(r.oid,true)) fingerprint FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
UNION ALL
SELECT 'publication'::text kind,p.oid::oid object_id,0::integer sub_id,md5(to_jsonb(p)::text) fingerprint FROM pg_publication p WHERE true
UNION ALL
SELECT 'publication_relation'::text kind,p.oid::oid object_id,0::integer sub_id,md5(to_jsonb(p)::text) fingerprint FROM pg_publication_rel p WHERE true
UNION ALL
SELECT 'defaults'::text kind,d.oid::oid object_id,0::integer sub_id,md5(to_jsonb(d)::text) fingerprint FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclnamespace=0 OR (n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema')
UNION ALL
SELECT 'column'::text kind,a.attrelid::oid object_id,a.attnum::integer sub_id,md5(to_jsonb(a)::text||coalesce(pg_get_expr(d.adbin,d.adrelid),'')) fingerprint FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema' AND a.attnum>0 AND NOT a.attisdropped
UNION ALL SELECT 'role_members',0::oid,0,md5(coalesce(string_agg(to_jsonb(m)::text,E'\n' ORDER BY m.roleid,m.member,m.grantor),'')) FROM pg_auth_members m;

CREATE TEMP TABLE k135_display_catalog_before ON COMMIT DROP AS
 SELECT * FROM pg_temp.k135_display_catalog_probe;
CREATE TEMP VIEW k135_display_row_inventory AS
 SELECT c.oid object_id,n.nspname schema_name,c.relname table_name,
  n.nspname LIKE 'karratha135\_%' ESCAPE '\' own135
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind IN('r','p') AND (n.nspname IN('public','auth','storage','karratha_pdc')
  OR n.nspname LIKE 'broome%' OR n.nspname LIKE 'pdc\_%\_private' ESCAPE '\'
  OR n.nspname LIKE 'karratha135\_%' ESCAPE '\'
  OR (n.nspname='cron' AND c.relname='job'));
CREATE TEMP TABLE k135_display_rows_before(object_id oid PRIMARY KEY,
 schema_name text NOT NULL,table_name text NOT NULL,own135 boolean NOT NULL,
 row_count bigint NOT NULL,row_hash text NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE k135_display_fence_proof(key text PRIMARY KEY,value jsonb NOT NULL) ON COMMIT DROP;
DO $display_fence_before$ DECLARE r record;row_count bigint;row_hash text; BEGIN
 FOR r IN SELECT * FROM pg_temp.k135_display_row_inventory ORDER BY schema_name,table_name LOOP
  EXECUTE format('SELECT count(*),md5(coalesce(string_agg(h,'''' ORDER BY h),'''')) FROM(SELECT md5(to_jsonb(x)::text) h FROM %I.%I x) q',r.schema_name,r.table_name)
   INTO row_count,row_hash;
  INSERT INTO pg_temp.k135_display_rows_before VALUES(r.object_id,r.schema_name,r.table_name,r.own135,row_count,row_hash);
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_temp.k135_display_rows_before) THEN RAISE EXCEPTION 'Protected records baseline missing';END IF;
END $display_fence_before$;

-- Local source candidate only. Parent creates the CLI migration and applies.
-- Five existing Karratha read ABI facades delegate to returned-display enrichment.
-- No PMB/Sales/Auth/native677 definitions, grants or operational writes change.
SET LOCAL search_path=public,extensions;
DO $environment$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')
  OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL THEN RAISE EXCEPTION 'Exact staging required';END IF;
 IF NOT EXISTS(SELECT 1 FROM karratha135_pdc.engine_release_135 WHERE singleton AND ready AND engine_version='pmb-native135-candidate-v1')
  THEN RAISE EXCEPTION 'Released native135 engine required';END IF;
END $environment$;
