DO $frozen_read_boundaries$ DECLARE r record; BEGIN
 FOR r IN SELECT * FROM pg_temp.k135_display_expected_facades LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure(r.signature)
   AND NOT p.prosecdef AND p.prorettype='jsonb'::regtype AND p.provolatile='v'
   AND encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex')=r.definition_sha256)
   THEN RAISE EXCEPTION 'Frozen own read facade changed: %',r.signature;END IF;
 END LOOP;
END $frozen_read_boundaries$;
