('karratha135_planner_access','require_vehicle_planner','','2667d6f8018f60a656512bf0f14c2f34eefcd71e27c2c37402912c7f23d1bc50','13b6ac0c1901c2adc088d3caabd0918a349304ff46d04b0248d88a176b14b4f6'),
('karratha135_usage','record_usage','p_batch_id uuid, p_page text, p_clicks integer, p_visit boolean','458af6cee44bae036881f12898a1eda76a501463b9173aeb850f743c6839ded9','02747147a60ab9d1e271f55383b87cfeae7ec0eda3b446383e2efd6d8ac29a9d'),
('karratha135_usage','report_usage','p_days integer','57bfdec3bae104a9503005a3624b1aec0efd4fc6b790574b5dbfd38cbbf9fcad','fc970939a155ad054c4c47a126435f752ce81985ab6330c990e7fd763ee09c48'),
('karratha135_priority','request','p_stock_number text, p_apply boolean, p_plan_hash text, p_idempotency_key uuid','9a2db29ae6c54365d44c4ec4fbb234b6e1911445abcd3ba5cb82d4bb77c5c352','8dc4738a1d1153c411abf7d9ad5ea27cb111b73f28e5b9949a9ca11b0ec5a581'),
('karratha135_priority','reschedule','p_vehicle uuid, p_floor timestamp with time zone','654e149428df0b00d752a54d965fde4e93d25a843758ab1dba20a660340e8c86','7e2566785ad141e8635d78ca420d6eaa2562d48725b786c334e6a3c6223a343b'),
('karratha135_priority','slot','p_booking uuid, p_bay uuid, p_minutes integer, p_floor timestamp with time zone, p_mode text','a2b827b9c3ecd47ba56d45f282de549af7c0fe74aed705fb0065324fa1cda0b7','e057d381fe37a9b62320fd4253a175df65d85f25ab22c600865c1e98d032e5c0'),
('karratha135_priority','state_hash','p_stock text, p_floor timestamp with time zone','b9d67244eb49c435556657390261dd99481e402ec860a77249c228280447ff88','3bef797ced7f5ee1f6ee14a6ddfa1e0940f5acf9b4d89ad11861a1fb7dcf8c65')
), actual AS (
 SELECT n.nspname schema_name,p.proname function_name,pg_get_function_identity_arguments(p.oid) identity_arguments,
  encode(extensions.digest(convert_to(replace(replace(p.prosrc,E'\r\n',E'\n'),E'\r',E'\n'),'UTF8'),'sha256'),'hex') body_sha256,
  encode(extensions.digest(convert_to(btrim(regexp_replace(replace(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'),E'\r',E'\n'),E'[ \t]+(\n|$)',E'\\1','g'),E'\n')||E'\n','UTF8'),'sha256'),'hex') definition_sha256
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname LIKE 'karratha135\_%' ESCAPE '\' AND p.prokind='f'
), checked AS (
 SELECT e.schema_name,e.function_name,e.identity_arguments,a.function_name IS NOT NULL present,
  a.body_sha256=e.body_sha256 body_matches,a.definition_sha256=e.definition_sha256 definition_matches
 FROM expected e LEFT JOIN actual a USING(schema_name,function_name,identity_arguments)
)
SELECT jsonb_build_object('expected_methods',count(*),'present_methods',count(*) FILTER(WHERE present),
 'exact_body_count',count(*) FILTER(WHERE body_matches),'exact_definition_count',count(*) FILTER(WHERE definition_matches),
 'ok',bool_and(present AND body_matches AND definition_matches),
 'mismatches',coalesce(jsonb_agg(jsonb_build_object('schema',schema_name,'name',function_name,'arguments',identity_arguments,
  'present',present,'body_matches',coalesce(body_matches,false),'definition_matches',coalesce(definition_matches,false)))
  FILTER(WHERE NOT coalesce(present AND body_matches AND definition_matches,false)),'[]'::jsonb)
) AS installed_native_definition_proof FROM checked;
$proof_before$ INTO STRICT v;
 IF v->>'ok' IS DISTINCT FROM 'true' OR (v->>'expected_methods')::int IS DISTINCT FROM 677
  OR (v->>'present_methods')::int IS DISTINCT FROM 677 OR (v->>'exact_body_count')::int IS DISTINCT FROM 677
  OR (v->>'exact_definition_count')::int IS DISTINCT FROM 677 THEN
  RAISE EXCEPTION 'Frozen native677 definition gate failed (before)';END IF;
END $native_before$;

-- Local candidate only: a returned-display overlay, never a workshop writer.
-- Helpers have no browser EXECUTE grant. The sole delegated boundary below
-- retains each existing native reader permission before source refresh.
CREATE FUNCTION karratha135_pdc.shared_navision_display_map_20261004(p_ids uuid[])
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER
SET search_path=pg_catalog,karratha135_pdc AS $display_map$
 WITH stock_counts AS MATERIALIZED (
  SELECT karratha135_pdc.normalize_vehicle_stock_number(coalesce(n.normalized_data->>'batch',n.normalized_data->>'stock','')) stock,
   count(*) match_count
  FROM karratha135_pdc.navision_backend_records n
  WHERE n.source_system='microsoft_navision' AND n.is_current AND n.record_status='current'
  GROUP BY 1
 ), owned AS MATERIALIZED (
  SELECT v.* FROM karratha135_pdc.vehicles v
  WHERE v.id=ANY(coalesce(p_ids,'{}'::uuid[])) AND v.deleted_at IS NULL
   AND EXISTS(SELECT 1 FROM karratha135_pdc.pdc_pilbara_service_operations o
    WHERE o.vehicle_id=v.id AND o.department='135')
 ), exact_source AS MATERIALIZED (
  SELECT v.id,v.vin canonical_vin,n.id source_id,n.normalized_data,t.shared_version,t.shared_updated_at
  FROM owned v
  JOIN karratha135_pdc.navision_backend_records n ON n.canonical_vehicle_id=v.id
   AND n.source_system='microsoft_navision' AND n.is_current AND n.record_status='current'
   AND btrim(coalesce(n.normalized_data->>'batch',n.normalized_data->>'stock',''))=btrim(v.stock_number)
  JOIN stock_counts c ON c.stock=karratha135_pdc.normalize_vehicle_stock_number(v.stock_number) AND c.match_count=1
  -- Native own activation/link changes can advance n.version/updated_at.
  -- The source epoch is deliberately the separate central-source tracker.
  JOIN karratha135_pdc.shared_navision_projection_state_135 t ON t.shared_record_id=n.id
  -- Only the already-owned source UUID is checked in the central master.
  -- Deleted/omitted/newer central evidence is never labelled current here.
  WHERE EXISTS(SELECT 1 FROM public.navision_backend_records central
   WHERE central.id=t.shared_record_id AND central.source_system='microsoft_navision'
    AND central.is_current AND central.record_status='current'
    AND central.version=t.shared_version AND central.updated_at=t.shared_updated_at
    AND central.dealer_code=n.dealer_code AND central.source_record_id=n.source_record_id
    AND central.normalized_data IS NOT DISTINCT FROM n.normalized_data)
  -- Another current central row for this already-owned stock makes the
  -- display binding ambiguous; no alternate row is ever chosen.
  AND NOT EXISTS(SELECT 1 FROM public.navision_backend_records duplicate
   WHERE duplicate.id<>n.id AND duplicate.source_system='microsoft_navision'
    AND duplicate.is_current AND duplicate.record_status='current'
    AND karratha135_pdc.normalize_vehicle_stock_number(coalesce(duplicate.normalized_data->>'batch',duplicate.normalized_data->>'stock',''))
     =karratha135_pdc.normalize_vehicle_stock_number(v.stock_number))
 ), display AS (
  SELECT s.id,jsonb_build_object(
   'eta_to_kewdale',karratha135_pdc.navision_kewdale_eta_from_payload(s.normalized_data),
   'shared_navision_display',jsonb_build_object('state','current','record_id',s.source_id,
    'source_version',s.shared_version,'source_updated_at',s.shared_updated_at)
  )||jsonb_strip_nulls(jsonb_build_object(
   'customer_name',coalesce(nullif(btrim(s.normalized_data->>'client'),''),nullif(btrim(s.normalized_data->>'toyotaCustomer'),''),
    nullif(btrim(s.normalized_data->>'customerSurname'),''),nullif(btrim(s.normalized_data->>'dealerCustomerName'),'')),
   'vehicle_description',coalesce(nullif(btrim(s.normalized_data->>'vehicle'),''),nullif(btrim(s.normalized_data->>'modelDescription'),''),nullif(btrim(s.normalized_data->>'toyotaVehicle'),'')),
   'model',coalesce(nullif(btrim(s.normalized_data->>'vehicle'),''),nullif(btrim(s.normalized_data->>'modelDescription'),''),nullif(btrim(s.normalized_data->>'toyotaVehicle'),'')),
   -- Display precedence accepts only complete valid source VINs. Blank
   -- component keys must not mask an authoritative full source VIN.
   'vin',coalesce(
    CASE WHEN karratha135_pdc.is_valid_vehicle_vin(s.normalized_data->>'vin')
     THEN karratha135_pdc.normalize_vehicle_vin(s.normalized_data->>'vin') END,
    CASE WHEN karratha135_pdc.is_valid_vehicle_vin(s.normalized_data->>'fullVin')
     THEN karratha135_pdc.normalize_vehicle_vin(s.normalized_data->>'fullVin') END,
    CASE WHEN karratha135_pdc.is_valid_vehicle_vin(s.normalized_data->>'frameVin')
     THEN karratha135_pdc.normalize_vehicle_vin(s.normalized_data->>'frameVin') END,
    karratha135_pdc.pdc_navision_effective_vin_471(s.normalized_data),
    CASE WHEN karratha135_pdc.is_valid_vehicle_vin(s.canonical_vin) THEN s.canonical_vin END),
   'toyota_order_number',coalesce(nullif(btrim(s.normalized_data->>'order'),''),karratha135_pdc.navision_original_column_value(s.normalized_data,'Order')),
   'navision_colour',coalesce(nullif(btrim(s.normalized_data->>'colourDescription'),''),nullif(btrim(s.normalized_data->>'colour'),'')),
   'colour',coalesce(nullif(btrim(s.normalized_data->>'colourDescription'),''),nullif(btrim(s.normalized_data->>'colour'),''))
  )) patch FROM exact_source s
 )
 SELECT coalesce(jsonb_object_agg(v.id::text,coalesce(d.patch,jsonb_build_object(
  'shared_navision_display',jsonb_build_object('state','source_unavailable')))),'{}'::jsonb)
 FROM owned v LEFT JOIN display d ON d.id=v.id;
$display_map$;
REVOKE ALL ON FUNCTION karratha135_pdc.shared_navision_display_map_20261004(uuid[]) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION karratha135_pdc.overlay_shared_navision_display_20261004(p_snapshot jsonb,p_shape text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path=pg_catalog,karratha135_pdc AS $display_overlay$
DECLARE result jsonb:=p_snapshot; vehicle_path text[];ids uuid[];display_map jsonb;rows jsonb;
 collection text;row_value jsonb;record_id text;patched_rows jsonb;
BEGIN
 IF p_shape IN('board','locations') THEN vehicle_path:=ARRAY['data','vehicles'];
 ELSIF p_shape IN('station','workshop') THEN vehicle_path:=ARRAY['vehicles'];
 ELSIF p_shape='eligibility' THEN vehicle_path:=ARRAY['candidates'];
 ELSE RAISE EXCEPTION 'Unknown owned display shape' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(result#>vehicle_path) IS DISTINCT FROM 'array' THEN RETURN result;END IF;
 WITH returned_ids AS (
  SELECT CASE WHEN p_shape='eligibility' THEN x#>>'{vehicle,id}' ELSE x->>'id' END id
   FROM jsonb_array_elements(result#>vehicle_path) x
  UNION SELECT x->>'vehicle_id' FROM jsonb_array_elements(CASE WHEN jsonb_typeof(result->'bookings')='array' THEN result->'bookings' ELSE '[]'::jsonb END) x
  UNION SELECT x->>'vehicle_id' FROM jsonb_array_elements(CASE WHEN jsonb_typeof(result->'active_stoppages')='array' THEN result->'active_stoppages' ELSE '[]'::jsonb END) x
 ) SELECT array_agg(id::uuid) INTO ids FROM returned_ids
 WHERE id~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
 display_map:=karratha135_pdc.shared_navision_display_map_20261004(ids);
 SELECT coalesce(jsonb_agg(CASE WHEN p_shape='eligibility' THEN
  CASE WHEN jsonb_typeof(x->'vehicle')='object'
   AND (NOT(x ? 'vehicle_id') OR x->>'vehicle_id'=x#>>'{vehicle,id}')
   THEN jsonb_set(x,ARRAY['vehicle'],(x->'vehicle')||coalesce(display_map->(x#>>'{vehicle,id}'),'{}'::jsonb),false)
   ELSE x END
  ELSE x||coalesce(display_map->(x->>'id'),'{}'::jsonb) END ORDER BY ord),'[]'::jsonb)
 INTO rows FROM jsonb_array_elements(result#>vehicle_path) WITH ORDINALITY e(x,ord);
 result:=jsonb_set(result,vehicle_path,rows,false);
 IF p_shape='workshop' THEN
  FOREACH collection IN ARRAY ARRAY['bookings','active_stoppages'] LOOP
   IF jsonb_typeof(result->collection) IS DISTINCT FROM 'array' THEN CONTINUE;END IF;
   patched_rows:='[]'::jsonb;
   FOR row_value IN SELECT value FROM jsonb_array_elements(result->collection) LOOP
    record_id:=row_value->>'vehicle_id';
    IF jsonb_typeof(row_value->'vehicle')='object' AND display_map ? record_id
     AND (NOT(row_value->'vehicle' ? 'id') OR row_value#>>'{vehicle,id}'=record_id)
     AND (NOT(row_value->'vehicle' ? 'vehicle_id') OR row_value#>>'{vehicle,vehicle_id}'=record_id) THEN
     row_value:=jsonb_set(row_value,ARRAY['vehicle'],(row_value->'vehicle')||(display_map->record_id),false);
    END IF;
    patched_rows:=patched_rows||jsonb_build_array(row_value);
   END LOOP;
   result:=jsonb_set(result,ARRAY[collection],patched_rows,false);
  END LOOP;
 END IF;
 RETURN result||jsonb_build_object('shared_navision_revision',
  (SELECT revision FROM karratha135_pdc.navision_backend_revision WHERE singleton));
END $display_overlay$;
REVOKE ALL ON FUNCTION karratha135_pdc.overlay_shared_navision_display_20261004(jsonb,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION karratha135_pdc.read_shared_navision_display_20261004(p_shape text,p_arguments jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,karratha135_pdc AS $display_boundary$
DECLARE result jsonb;reader_role text;
BEGIN
 PERFORM karratha135_pdc.require_active_session_135();
 IF jsonb_typeof(p_arguments) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid owned reader arguments' USING ERRCODE='22023';END IF;
 CASE p_shape
 WHEN 'board','locations' THEN
  IF p_arguments<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid owned reader arguments' USING ERRCODE='22023';END IF;
  reader_role:=karratha135_pdc.current_pdc_user_role()::text;
  IF reader_role IS NULL OR reader_role NOT IN('viewer','operator','importer','administrator') THEN
   IF p_shape='board' THEN RETURN karratha135_pdc.get_pdc_email_vehicle_board_snapshot();
   ELSE RETURN karratha135_pdc.get_pdc_email_vehicle_location_snapshot();END IF;
  END IF;
 WHEN 'eligibility' THEN
  IF p_arguments<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid owned reader arguments' USING ERRCODE='22023';END IF;
  PERFORM karratha135_pdc.require_pdc_role('viewer');
 WHEN 'station' THEN
  IF p_arguments-ARRAY['stage_code','date_from','date_to']<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid owned reader arguments' USING ERRCODE='22023';END IF;
  PERFORM karratha135_pdc.workshop_require_planner_operator();
 WHEN 'workshop' THEN
  IF p_arguments-ARRAY['date_from','date_to']<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid owned reader arguments' USING ERRCODE='22023';END IF;
  PERFORM karratha135_pdc.require_pdc_role('operator');
 ELSE RAISE EXCEPTION 'Unknown owned display reader' USING ERRCODE='22023';
 END CASE;
 -- This is the existing authorised, centre-scoped metadata projector. It
 -- reads the central source and never imports shared operational identities.
 PERFORM karratha135_pdc.refresh_shared_navision_135(NULL);
 CASE p_shape
 WHEN 'board' THEN result:=karratha135_pdc.get_pdc_email_vehicle_board_snapshot();
 WHEN 'locations' THEN result:=karratha135_pdc.get_pdc_email_vehicle_location_snapshot();
 WHEN 'eligibility' THEN result:=karratha135_pdc.get_workshop_eligibility_snapshot();
 WHEN 'station' THEN result:=karratha135_pdc.get_station_workshop_snapshot(p_arguments->>'stage_code',(p_arguments->>'date_from')::date,(p_arguments->>'date_to')::date);
 WHEN 'workshop' THEN result:=karratha135_pdc.get_workshop_snapshot((p_arguments->>'date_from')::date,(p_arguments->>'date_to')::date);
 END CASE;
 RETURN karratha135_pdc.overlay_shared_navision_display_20261004(result,p_shape);
END $display_boundary$;
REVOKE ALL ON FUNCTION karratha135_pdc.read_shared_navision_display_20261004(text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
-- Private implementation delegation for the already approved five INVOKER
-- read facades. No new public RPC, table grant or exposed schema is created.
GRANT EXECUTE ON FUNCTION karratha135_pdc.read_shared_navision_display_20261004(text,jsonb) TO authenticated;

