('karratha135_priority','request','p_stock_number text, p_apply boolean, p_plan_hash text, p_idempotency_key uuid','9a2db29ae6c54365d44c4ec4fbb234b6e1911445abcd3ba5cb82d4bb77c5c352','8dc4738a1d1153c411abf7d9ad5ea27cb111b73f28e5b9949a9ca11b0ec5a581'),
('karratha135_priority','reschedule','p_vehicle uuid, p_floor timestamp with time zone','654e149428df0b00d752a54d965fde4e93d25a843758ab1dba20a660340e8c86','7e2566785ad141e8635d78ca420d6eaa2562d48725b786c334e6a3c6223a343b'),
('karratha135_priority','slot','p_booking uuid, p_bay uuid, p_minutes integer, p_floor timestamp with time zone, p_mode text','a2b827b9c3ecd47ba56d45f282de549af7c0fe74aed705fb0065324fa1cda0b7','e057d381fe37a9b62320fd4253a175df65d85f25ab22c600865c1e98d032e5c0'),
('karratha135_priority','state_hash','p_stock text, p_floor timestamp with time zone','b9d67244eb49c435556657390261dd99481e402ec860a77249c228280447ff88','3bef797ced7f5ee1f6ee14a6ddfa1e0940f5acf9b4d89ad11861a1fb7dcf8c65')
), actual AS (
 SELECT n.nspname schema_name,p.proname function_name,pg_get_function_identity_arguments(p.oid) identity_arguments,
  encode(extensions.digest(convert_to(replace(replace(p.prosrc,E'\r\n',E'\n'),E'\r',E'\n'),'UTF8'),'sha256'),'hex') body_sha256,
  encode(extensions.digest(convert_to(btrim(regexp_replace(replace(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'),E'\r',E'\n'),E'[ \t]+(\n|$)',E'\\1','g'),E'\n')||E'\n','UTF8'),'sha256'),'hex') definition_sha256
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname LIKE 'karratha135\_%' ESCAPE '\' AND p.prokind='f'
), checked AS (
 SELECT e.schema_name,e.function_name,e.identity_arguments,a.function_name IS NOT NULL present,
  a.body_sha256=e.body_sha256 body_matches,a.definition_sha256=e.definition_sha256 definition_matches
 FROM expected e LEFT JOIN actual a USING(schema_name,function_name,identity_arguments)
)
SELECT jsonb_build_object('expected_methods',count(*),'present_methods',count(*) FILTER(WHERE present),
 'exact_body_count',count(*) FILTER(WHERE body_matches),'exact_definition_count',count(*) FILTER(WHERE definition_matches),
 'ok',bool_and(present AND body_matches AND definition_matches),
 'mismatches',coalesce(jsonb_agg(jsonb_build_object('schema',schema_name,'name',function_name,'arguments',identity_arguments,
  'present',present,'body_matches',coalesce(body_matches,false),'definition_matches',coalesce(definition_matches,false)))
  FILTER(WHERE NOT coalesce(present AND body_matches AND definition_matches,false)),'[]'::jsonb)
) AS installed_native_definition_proof FROM checked;
$proof_after$ INTO STRICT v;
 IF v->>'ok' IS DISTINCT FROM 'true' OR (v->>'expected_methods')::int IS DISTINCT FROM 677
  OR (v->>'present_methods')::int IS DISTINCT FROM 677 OR (v->>'exact_body_count')::int IS DISTINCT FROM 677
  OR (v->>'exact_definition_count')::int IS DISTINCT FROM 677 THEN
  RAISE EXCEPTION 'Frozen native677 definition gate failed (after)';END IF;
END $native_after$;

DO $all_other_functions_unchanged$ DECLARE r record; BEGIN
 FOR r IN SELECT b.* FROM pg_temp.k135_display_existing_functions b LOOP
  IF EXISTS(SELECT 1 FROM pg_temp.k135_display_expected_facades e WHERE to_regprocedure(e.signature)::oid=r.oid) THEN
   IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=r.oid AND to_jsonb(p)-'prosrc'=r.attributes)
    THEN RAISE EXCEPTION 'Own facade metadata/owner/ACL changed: %',r.proname;END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=r.oid AND md5(to_jsonb(p)::text||pg_get_functiondef(p.oid))=r.fingerprint) THEN
   RAISE EXCEPTION 'Protected function definition/ACL/owner changed: %',r.proname;
  END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE p.prokind IN('f','p') AND n.nspname NOT LIKE 'pg\_%' ESCAPE '\' AND n.nspname<>'information_schema'
   AND NOT EXISTS(SELECT 1 FROM pg_temp.k135_display_existing_functions b WHERE b.oid=p.oid)
   AND NOT(n.nspname='karratha135_pdc' AND p.proname IN('shared_navision_display_map_20261004','overlay_shared_navision_display_20261004','read_shared_navision_display_20261004')))
  THEN RAISE EXCEPTION 'Unreviewed new function outside exact private display layer';END IF;
 IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='karratha135_pdc'
  AND p.proname IN('shared_navision_display_map_20261004','overlay_shared_navision_display_20261004','read_shared_navision_display_20261004'))<>3
  THEN RAISE EXCEPTION 'Unexpected private display helper overload';END IF;
END $all_other_functions_unchanged$;

-- Run after candidate installation, or after all own test rows were rolled back.
DO $display_fence_after$ DECLARE r record;row_count bigint;row_hash text;catalogue_count bigint;
 relation_count bigint;own_relation_count bigint;catalogue_digest text;records_digest text; BEGIN
 PERFORM set_config('search_path','public,extensions',true);
 IF EXISTS((SELECT * FROM pg_temp.k135_display_catalog_before
  EXCEPT SELECT * FROM pg_temp.k135_display_catalog_probe)
  UNION ALL(SELECT * FROM pg_temp.k135_display_catalog_probe
  EXCEPT SELECT * FROM pg_temp.k135_display_catalog_before)) THEN
  RAISE EXCEPTION 'Protected outside-own catalogue/ACL/policy/column changed';END IF;
 IF EXISTS((SELECT b.object_id,b.schema_name,b.table_name,b.own135 FROM pg_temp.k135_display_rows_before b
  EXCEPT SELECT i.object_id,i.schema_name,i.table_name,i.own135 FROM pg_temp.k135_display_row_inventory i)
  UNION ALL(SELECT i.object_id,i.schema_name,i.table_name,i.own135 FROM pg_temp.k135_display_row_inventory i
  EXCEPT SELECT b.object_id,b.schema_name,b.table_name,b.own135 FROM pg_temp.k135_display_rows_before b)) THEN
  RAISE EXCEPTION 'Protected relation inventory changed';END IF;
 FOR r IN SELECT b.* FROM pg_temp.k135_display_rows_before b ORDER BY b.schema_name,b.table_name LOOP
  EXECUTE format('SELECT count(*),md5(coalesce(string_agg(h,'''' ORDER BY h),'''')) FROM(SELECT md5(to_jsonb(x)::text) h FROM %I.%I x) q',r.schema_name,r.table_name)
   INTO row_count,row_hash;
  IF row_count IS DISTINCT FROM r.row_count OR row_hash IS DISTINCT FROM r.row_hash THEN
   RAISE EXCEPTION 'Protected outside-own records changed: %.%',r.schema_name,r.table_name;END IF;
 END LOOP;
 SELECT count(*),md5(string_agg(c.kind||':'||c.object_id||':'||c.sub_id||':'||c.fingerprint,E'\n'
  ORDER BY c.kind,c.object_id,c.sub_id)) INTO catalogue_count,catalogue_digest FROM pg_temp.k135_display_catalog_before c;
 SELECT count(*) FILTER(WHERE NOT b.own135),count(*) FILTER(WHERE b.own135),
  md5(string_agg(b.object_id||':'||b.row_count||':'||b.row_hash,E'\n' ORDER BY b.object_id))
  INTO relation_count,own_relation_count,records_digest FROM pg_temp.k135_display_rows_before b;
 IF catalogue_count<=0 OR relation_count<=0 OR catalogue_digest IS NULL OR records_digest IS NULL THEN
  RAISE EXCEPTION 'Complete protected display-layer proof missing';END IF;
 INSERT INTO pg_temp.k135_display_fence_proof VALUES('protected',jsonb_build_object('ok',true,
  'catalogue_objects',catalogue_count,'protected_relations',relation_count,'own_relations_unchanged',own_relation_count,
  'catalogue_digest',catalogue_digest,'records_digest',records_digest,
  'five_own_facade_body_changes_allowed',true,'native677_proof_embedded_in_candidate',true,
  'all_protected_rows_unchanged',true,'sequence_counters_compared',false));
END $display_fence_after$;
SELECT value AS protected_display_installation FROM pg_temp.k135_display_fence_proof WHERE key='protected';
